function check([stamp, target], actual, expected) {
  if (!Array.isArray(actual)) return false;
  // An empty answer claims that target cannot be made, which is right only when the reference agrees.
  if (actual.length === 0) return Array.isArray(expected) && expected.length === 0;
  const n = target.length, m = stamp.length;
  if (actual.length > 10 * n) return false;
  if (actual.some(p => !Number.isInteger(p) || p < 0 || p > n - m)) return false;
  // Replay the turns backwards: each position keeps the letter of the last turn that covers it.
  // next[j] skips to the first position at or after j that no later turn has fixed yet.
  const next = Array.from({ length: n + 1 }, (_, j) => j);
  const find = j => {
    while (next[j] !== j) { next[j] = next[next[j]]; j = next[j]; }
    return j;
  };
  let fixed = 0;
  for (let t = actual.length - 1; t >= 0; t--) {
    const p = actual[t];
    for (let j = find(p); j < p + m; j = find(j)) {
      if (stamp[j - p] !== target[j]) return false;
      next[j] = j + 1;
      fixed++;
    }
  }
  return fixed === n;
}

