function validate([stamp, target]) {
  if (typeof stamp !== 'string' || typeof target !== 'string') return 'stamp and target must be strings.';
  if (stamp.length < 1 || target.length > 1000) return 'Lengths must satisfy 1 <= stamp.length <= target.length <= 1000.';
  if (stamp.length > target.length) return 'stamp cannot be longer than target.';
  if (!/^[a-z]+$/.test(stamp) || !/^[a-z]+$/.test(target)) return 'Use only lowercase English letters.';
  return null;
}

