function movesToStamp(stamp, target) {
  const m = stamp.length;
  const n = target.length;
  const windows = n - m + 1;
  const missing = new Array(windows).fill(0);
  const queue = [];
  for (let i = 0; i < windows; i++) {
    for (let k = 0; k < m; k++) {
      if (target[i + k] !== stamp[k]) {
        missing[i]++;
      }
    }
    if (missing[i] === 0) {
      queue.push(i);
    }
  }

  const done = new Array(n).fill(false);
  let covered = 0;
  for (let head = 0; head < queue.length; head++) {
    const start = queue[head];
    for (let j = start; j < start + m; j++) {
      if (done[j]) {
        continue;
      }
      done[j] = true;
      covered++;
      const first = Math.max(0, j - m + 1);
      const last = Math.min(windows - 1, j);
      for (let w = first; w <= last; w++) {
        if (target[j] !== stamp[j - w]) {
          missing[w]--;
          if (missing[w] === 0) {
            queue.push(w);
          }
        }
      }
    }
  }
  return covered === n ? queue.reverse() : [];
}

