function movesToStamp(stamp, target) {
  // Undo stamps on a copy of target until no window can be undone, rescanning from the left each pass.
  const chars = target.split('');
  const m = stamp.length;
  const undone = [];
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + m <= chars.length; i++) {
      let fits = true, useful = false;
      for (let k = 0; k < m && fits; k++) {
        if (chars[i + k] === '?') continue;
        if (chars[i + k] !== stamp[k]) fits = false;
        else useful = true;
      }
      if (fits && useful) {
        for (let k = 0; k < m; k++) chars[i + k] = '?';
        undone.push(i);
        changed = true;
      }
    }
  }
  return chars.every(c => c === '?') ? undone.reverse() : [];
}

