function generate(rand, size) {
  const large = size === 'large';
  const alphabet = rand() < 0.5 ? 'ab' : 'abc';
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  let m, n;
  if (large) {
    const shape = rand();
    m = shape < 0.3 ? 1 + Math.floor(rand() * 5) : shape < 0.7 ? 10 + Math.floor(rand() * 40) : 150 + Math.floor(rand() * 250);
    n = 1000;
  } else {
    m = 1 + Math.floor(rand() * 3);
    n = m + Math.floor(rand() * (9 - m));
  }
  const stamp = Array.from({ length: m }, letter).join('');
  if (!large && rand() < 0.35) return [stamp, Array.from({ length: n }, letter).join('')];
  // Build a reachable target by really stamping, then stamping over every position still left as '?'.
  const chars = new Array(n).fill('?');
  const press = p => { for (let k = 0; k < m; k++) chars[p + k] = stamp[k]; };
  const turns = large ? 5 + Math.floor(rand() * 60) : Math.floor(rand() * 4);
  for (let t = 0; t < turns; t++) press(Math.floor(rand() * (n - m + 1)));
  for (let j = 0; j < n; j++) if (chars[j] === '?') press(Math.min(j, n - m));
  // Sometimes change one letter, which usually makes the target unreachable.
  if (rand() < (large ? 0.25 : 0.3)) chars[Math.floor(rand() * n)] = letter();
  return [stamp, chars.join('')];
}
